def solve(model, tokenizer, dataset, tools):
    # Average each head’s ablation effect across public examples.
    scores = []
    for layer in range(model.n_layers):
        for head in range(model.n_heads):
            drops = [tools.ablate_head(item["tokens"], layer, head)["drop"] for item in dataset]
            scores.append((sum(drops) / len(drops), layer, head))
    _, layer, head = max(scores)
    print("Top candidates:", sorted(scores, reverse=True)[:5])
    return {"components": [{"type": "attention_head", "layer": layer, "head": head}]}
